import sys

def main():
    import sys
    import collections

    input = sys.stdin.read().split()
    n = int(input[0])
    words = input[1:]

    def abbreviate(text, start1, end1, start2, end2):
        abbr = ''.join(w[0].upper() for w in text[start1:end1+1])
        new_text = text[:start1] + [abbr] + text[end1+1:start2] + [abbr] + text[end2+1:]
        return len(' '.join(new_text))

    min_length = len(' '.join(words))
    for i in range(n):
        for j in range(i + 1, n):
            segment1 = words[i:j+1]
            for k in range(j + 2, n - (j - i)):
                l = k + (j - i)
                if words[k:l+1] == segment1:
                    min_length = min(min_length, abbreviate(words, i, j, k, l))

    print(min_length)

if __name__ == "__main__":
    main()
